{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

var version = "v0.0.0-SNAPSHOT"

type checker struct {
	name         string
	tags         []string
	description  string
	nonCompliant string
	compliant    string
}

var checkers []checker

func main() {
	if len(os.Args) < 2 {
		fmt.Println("no args provided")
		return
	}

	cmd := os.Args[1]
	switch cmd {
	case "version":
		fmt.Printf("go-critic version: %s\n", version)
	case "help":
		printHelp()
	case "doc":
		handleDoc(os.Args[2:])
	case "check":
		handleCheck(os.Args[2:])
	default:
		if strings.HasPrefix(cmd, "-") {
			fmt.Printf("%q unknown command\nRun \"go-critic help\" for usage.\n\nno such command %q\n", cmd, cmd)
		} else {
			fmt.Printf("unknown command %q\n", cmd)
		}
	}
}

func printHelp() {
	fmt.Println(`Usage:

    go-critic <command> [arguments...]

The commands are:

    check             run linter over specified targets
    doc               get installed checkers documentation
    help              shows help message
    version           shows version of the application

Version: ` + version)
}

func handleDoc(args []string) {
	if len(args) == 0 {
		for _, c := range checkers {
			fmt.Printf("%s [%s]\n", c.name, strings.Join(c.tags, " "))
		}
		return
	}

	if args[0] == "-help" {
		fmt.Println("Usage: go-critic doc [checkerName]")
		return
	}

	name := args[0]
	for _, c := range checkers {
		if c.name == name {
			fmt.Printf("%s checker documentation\n", c.name)
			fmt.Printf("URL: https://github.com/go-critic/go-critic/checkers\n")
			fmt.Printf("Tags: [%s]\n\n", strings.Join(c.tags, " "))
			fmt.Printf("%s\n\n", c.description)
			fmt.Printf("Non-compliant code:\n%s\n\n", c.nonCompliant)
			fmt.Printf("Compliant code:\n%s\n", c.compliant)
			return
		}
	}
	fmt.Printf("checker %s not found\n", name)
}

func hasTag(c checker, tag string) bool {
	for _, t := range c.tags {
		if "#"+t == tag {
			return true
		}
	}
	return false
}

func handleCheck(args []string) {
	fs := flag.NewFlagSet("check", flag.ContinueOnError)
	enable := fs.String("enable", "", "")
	disable := fs.String("disable", "", "")
	enableAll := fs.Bool("enableAll", false, "")
	verbose := fs.Bool("v", false, "")
	fs.Usage = func() {}

	err := fs.Parse(args)
	if err != nil {
		return
	}

	targets := fs.Args()
	if len(targets) == 0 {
		targets = []string{"."}
	}

	enabledMap := make(map[string]bool)
	for _, c := range checkers {
		isEnabled := true
		for _, t := range c.tags {
			if t == "experimental" || t == "opinionated" {
				isEnabled = false
				break
			}
		}
		if *enableAll {
			isEnabled = true
		}
		enabledMap[c.name] = isEnabled
	}

	if *enable != "" {
		for _, name := range strings.Split(*enable, ",") {
			if strings.HasPrefix(name, "#") {
				for _, c := range checkers {
					if hasTag(c, name) {
						enabledMap[c.name] = true
					}
				}
			} else {
				enabledMap[name] = true
			}
		}
	}

	if *disable != "" {
		for _, name := range strings.Split(*disable, ",") {
			if strings.HasPrefix(name, "#") {
				for _, c := range checkers {
					if hasTag(c, name) {
						enabledMap[c.name] = false
					}
				}
			} else {
				enabledMap[name] = false
			}
		}
	}

	if *verbose {
		var names []string
		for name := range enabledMap {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			if enabledMap[name] {
				// We'll skip some debug info for now but we should try to match the original output if possible
			} else {
				fmt.Printf("\tdebug: %s: not enabled by name or tag (-enable)\n", name)
			}
		}
		for _, name := range names {
			if enabledMap[name] {
				fmt.Printf("\tdebug: %s is enabled\n", name)
			}
		}
	}

	exitCode := 0
	for _, target := range targets {
		if strings.HasSuffix(target, "/...") {
			dir := strings.TrimSuffix(target, "/...")
			err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if !info.IsDir() && strings.HasSuffix(path, ".go") {
					if runCheckersOnFile(path, enabledMap, *verbose) {
						exitCode = 1
					}
				}
				return nil
			})
			if err != nil {
				fmt.Fprintf(os.Stderr, "error walking %s: %v\n", target, err)
			}
		} else {
			info, err := os.Stat(target)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error stating %s: %v\n", target, err)
				continue
			}
			if info.IsDir() {
				// Handle directory as a package (all .go files in it)
				files, _ := filepath.Glob(filepath.Join(target, "*.go"))
				for _, f := range files {
					if runCheckersOnFile(f, enabledMap, *verbose) {
						exitCode = 1
					}
				}
			} else {
				if runCheckersOnFile(target, enabledMap, *verbose) {
					exitCode = 1
				}
			}
		}
	}
	os.Exit(exitCode)
}

func runCheckersOnFile(path string, enabledMap map[string]bool, verbose bool) bool {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		return false
	}

	if verbose {
		// Matching original output: \tdebug: checking "command-line-arguments" package (1 files)
		// This is hard to match exactly without package loading.
	}

	found := false
	ast.Inspect(f, func(n ast.Node) bool {
		// assignOp
		if enabledMap["assignOp"] {
			if assign, ok := n.(*ast.AssignStmt); ok && len(assign.Lhs) == 1 && len(assign.Rhs) == 1 && assign.Tok == token.ASSIGN {
				if binary, ok := assign.Rhs[0].(*ast.BinaryExpr); ok {
					lhs := fmt.Sprintf("%v", assign.Lhs[0])
					blhs := fmt.Sprintf("%v", binary.X)
					brhs := fmt.Sprintf("%v", binary.Y)

					var op string
					var replacement string

					if lhs == blhs {
						switch binary.Op {
						case token.ADD:
							if brhs == "1" {
								replacement = lhs + "++"
							} else {
								op = "+="
								replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
							}
						case token.SUB:
							if brhs == "1" {
								replacement = lhs + "--"
							} else {
								op = "-="
								replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
							}
						case token.MUL:
							op = "*="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.QUO:
							op = "/="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.REM:
							op = "%="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.AND:
							op = "&="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.OR:
							op = "|="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.XOR:
							op = "^="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.SHL:
							op = "<<="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.SHR:
							op = ">>="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						}
					}

					if replacement != "" {
						fmt.Printf("%s:%d:%d: assignOp: replace `%s = %s %s %s` with `%s`\n", 
							path, fset.Position(assign.Pos()).Line, fset.Position(assign.Pos()).Column,
							lhs, blhs, binary.Op, brhs, replacement)
						found = true
					}
				}
			}
		}

		// elseif
		if enabledMap["elseif"] {
			if ifStmt, ok := n.(*ast.IfStmt); ok && ifStmt.Else != nil {
				if block, ok := ifStmt.Else.(*ast.BlockStmt); ok && len(block.List) == 1 {
					if _, ok := block.List[0].(*ast.IfStmt); ok {
						fmt.Printf("%s:%d:%d: elseif: can replace 'else {if cond {}}' with 'else if cond {}'\n",
							path, fset.Position(ifStmt.Else.Pos()).Line, fset.Position(ifStmt.Else.Pos()).Column)
						found = true
					}
				}
			}
		}

		// unslice
		if enabledMap["unslice"] {
			if slice, ok := n.(*ast.SliceExpr); ok && slice.Low == nil && slice.High == nil && slice.Max == nil {
				fmt.Printf("%s:%d:%d: unslice: could simplify %v[:] to %v\n",
					path, fset.Position(slice.Pos()).Line, fset.Position(slice.Pos()).Column, slice.X, slice.X)
				found = true
			}
		}

		return true
	})
	return found
}

