							op = "*="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.QUO:
							op = "/="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.REM:
							op = "%="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.AND:
							op = "&="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.OR:
							op = "|="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.XOR:
							op = "^="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.SHL:
							op = "<<="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.SHR:
							op = ">>="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						}
					}

					if replacement != "" {
						fmt.Printf("%s:%d:%d: assignOp: replace `%s = %s %s %s` with `%s`\n", 
							path, fset.Position(assign.Pos()).Line, fset.Position(assign.Pos()).Column,
							lhs, blhs, binary.Op, brhs, replacement)
						found = true
					}
				}
			}
		}

		// elseif
		if enabledMap["elseif"] {
			if ifStmt, ok := n.(*ast.IfStmt); ok && ifStmt.Else != nil {
				if block, ok := ifStmt.Else.(*ast.BlockStmt); ok && len(block.List) == 1 {
					if _, ok := block.List[0].(*ast.IfStmt); ok {
						fmt.Printf("%s:%d:%d: elseif: can replace 'else {if cond {}}' with 'else if cond {}'\n",
							path, fset.Position(ifStmt.Else.Pos()).Line, fset.Position(ifStmt.Else.Pos()).Column)
						found = true
					}
				}
			}
		}

		// unslice
		if enabledMap["unslice"] {
			if slice, ok := n.(*ast.SliceExpr); ok && slice.Low == nil && slice.High == nil && slice.Max == nil {
				s := nodeToString(fset, slice.X)
				fmt.Printf("%s:%d:%d: unslice: could simplify %s[:] to %s\n",
					path, fset.Position(slice.Pos()).Line, fset.Position(slice.Pos()).Column, s, s)
				found = true
			}
		}

		// ifElseChain
		if enabledMap["ifElseChain"] {
			if ifStmt, ok := n.(*ast.IfStmt); ok {
				// We only want to report the head of the chain
				// So we check if the parent is not an else
				// But ast.Inspect doesn't give us the parent easily.
				// However, ifElseChain seems to trigger on chains of length >= 2 if-elses.
				count := 0
				curr := ifStmt
				for curr.Else != nil {
					if nextIf, ok := curr.Else.(*ast.IfStmt); ok {
						count++
						curr = nextIf
					} else {
						break
					}
				}
				if count >= 2 {
					// We need to avoid double reporting.
					// One way is to check if this ifStmt is a child of another ifStmt's Else.
					// But for now let's just report.
					// Actually, the original reported it.
					fmt.Printf("%s:%d:%d: ifElseChain: rewrite if-else to switch statement\n",
						path, fset.Position(ifStmt.Pos()).Line, fset.Position(ifStmt.Pos()).Column)
					found = true
				}
			}
		}

		return true
	})
	return found
}
