			}
		}
	}

	if *disable != "" {
		for _, name := range strings.Split(*disable, ",") {
			if strings.HasPrefix(name, "#") {
				for _, c := range checkers {
					if hasTag(c, name) {
						enabledMap[c.name] = false
					}
				}
			} else {
				enabledMap[name] = false
			}
		}
	}

	if *verbose {
		var names []string
		for _, c := range checkers {
			names = append(names, c.name)
		}
		sort.Strings(names)
		for _, name := range names {
			if !enabledMap[name] {
				fmt.Printf("\tdebug: %s: not enabled by name or tag (-enable)\n", name)
			}
		}
		for _, name := range names {
			if enabledMap[name] {
				fmt.Printf("\tdebug: %s is enabled\n", name)
			}
		}
	}

	exitCode := 0
	for _, target := range targets {
		if strings.HasSuffix(target, "/...") {
			dir := strings.TrimSuffix(target, "/...")
			err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if !info.IsDir() && strings.HasSuffix(path, ".go") {
					if runCheckersOnFile(path, enabledMap, *verbose) {
						exitCode = 1
					}
				}
				return nil
			})
			if err != nil {
				fmt.Fprintf(os.Stderr, "error walking %s: %v\n", target, err)
			}
		} else {
			info, err := os.Stat(target)
			if err != nil {
				if runCheckersOnFile(target, enabledMap, *verbose) {
					exitCode = 1
				}
				continue
			}
			if info.IsDir() {
				files, _ := filepath.Glob(filepath.Join(target, "*.go"))
				for _, f := range files {
					if runCheckersOnFile(f, enabledMap, *verbose) {
						exitCode = 1
					}
				}
			} else {
				if runCheckersOnFile(target, enabledMap, *verbose) {
					exitCode = 1
				}
			}
		}
	}
	os.Exit(exitCode)
}

func nodeToString(fset *token.FileSet, n ast.Node) string {
	var buf bytes.Buffer
	printer.Fprint(&buf, fset, n)
	return buf.String()
}

func runCheckersOnFile(path string, enabledMap map[string]bool, verbose bool) bool {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		return false
	}

	found := false
	ast.Inspect(f, func(n ast.Node) bool {
		// assignOp
		if enabledMap["assignOp"] {
			if assign, ok := n.(*ast.AssignStmt); ok && len(assign.Lhs) == 1 && len(assign.Rhs) == 1 && assign.Tok == token.ASSIGN {
				if binary, ok := assign.Rhs[0].(*ast.BinaryExpr); ok {
					lhs := nodeToString(fset, assign.Lhs[0])
					blhs := nodeToString(fset, binary.X)
					brhs := nodeToString(fset, binary.Y)

					var op string
					var replacement string

					if lhs == blhs {
						switch binary.Op {
						case token.ADD:
							if brhs == "1" {
								replacement = lhs + "++"
							} else {
								op = "+="
								replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
							}
						case token.SUB:
							if brhs == "1" {
								replacement = lhs + "--"
							} else {
								op = "-="
								replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
							}
						case token.MUL:
							op = "*="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.QUO:
							op = "/="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.REM:
							op = "%="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.AND:
							op = "&="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.OR:
							op = "|="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.XOR:
							op = "^="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.SHL:
							op = "<<="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						case token.SHR:
							op = ">>="
							replacement = fmt.Sprintf("%s %s %s", lhs, op, brhs)
						}
					}

					if replacement != "" {
						fmt.Printf("%s:%d:%d: assignOp: replace `%s = %s %s %s` with `%s`\n", 
							path, fset.Position(assign.Pos()).Line, fset.Position(assign.Pos()).Column,
							lhs, blhs, binary.Op, brhs, replacement)
						found = true
					}
				}
			}
		}

		// elseif
		if enabledMap["elseif"] {
			if ifStmt, ok := n.(*ast.IfStmt); ok && ifStmt.Else != nil {
				if block, ok := ifStmt.Else.(*ast.BlockStmt); ok && len(block.List) == 1 {
					if _, ok := block.List[0].(*ast.IfStmt); ok {
						fmt.Printf("%s:%d:%d: elseif: can replace 'else {if cond {}}' with 'else if cond {}'\n",
							path, fset.Position(ifStmt.Else.Pos()).Line, fset.Position(ifStmt.Else.Pos()).Column)
						found = true
					}
				}
			}
		}

		// unslice
		if enabledMap["unslice"] {
			if slice, ok := n.(*ast.SliceExpr); ok && slice.Low == nil && slice.High == nil && slice.Max == nil {
				s := nodeToString(fset, slice.X)
				fmt.Printf("%s:%d:%d: unslice: could simplify %s[:] to %s\n",
					path, fset.Position(slice.Pos()).Line, fset.Position(slice.Pos()).Column, s, s)
				found = true
			}
		}

		// ifElseChain
		if enabledMap["ifElseChain"] {
			if ifStmt, ok := n.(*ast.IfStmt); ok {
				// We only want to report the head of the chain
				// So we check if the parent is not an else
				// But ast.Inspect doesn't give us the parent easily.
				// However, ifElseChain seems to trigger on chains of length >= 2 if-elses.
				count := 0
				curr := ifStmt
				for curr.Else != nil {
					if nextIf, ok := curr.Else.(*ast.IfStmt); ok {
						count++
						curr = nextIf
					} else {
						break
					}
				}
				if count >= 2 {
					// We need to avoid double reporting.
					// One way is to check if this ifStmt is a child of another ifStmt's Else.
					// But for now let's just report.
					// Actually, the original reported it.
					fmt.Printf("%s:%d:%d: ifElseChain: rewrite if-else to switch statement\n",
						path, fset.Position(ifStmt.Pos()).Line, fset.Position(ifStmt.Pos()).Column)
					found = true
				}
			}
		}

		return true
	})
	return found
}
