{"command":"cat <<'EOF' > main.go
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var version = "v0.0.0-SNAPSHOT"

type checker struct {
	name         string
	tags         []string
	description  string
	nonCompliant string
	compliant    string
}

var checkers []checker

type issue struct {
	pos     token.Position
	checker string
	message string
}

func main() {
	if len(os.Args) < 2 {
		fmt.Println("no args provided")
		return
	}

	cmd := os.Args[1]
	switch cmd {
	case "version":
		fmt.Printf("go-critic version: %s\n", version)
	case "help":
		printHelp()
	case "doc":
		handleDoc(os.Args[2:])
	case "check":
		handleCheck(os.Args[2:])
	default:
		if strings.HasPrefix(cmd, "-") {
			fmt.Printf("%q unknown command\nRun \"go-critic help\" for usage.\n\nno such command %q\n", cmd, cmd)
		} else {
			fmt.Printf("unknown command %q\n", cmd)
		}
	}
}

func printHelp() {
	fmt.Println(`Usage:

    go-critic <command> [arguments...]

The commands are:

    check             run linter over specified targets
    doc               get installed checkers documentation
    help              shows help message
    version           shows version of the application

Version: ` + version)
}

func handleDoc(args []string) {
	if len(args) == 0 {
		for _, c := range checkers {
			fmt.Printf("%s [%s]\n", c.name, strings.Join(c.tags, " "))
		}
		return
	}

	if args[0] == "-help" {
		fmt.Println("Usage: go-critic doc [checkerName]")
		return
	}

	name := args[0]
	for _, c := range checkers {
		if c.name == name {
			fmt.Printf("%s checker documentation\n", c.name)
			fmt.Printf("URL: https://github.com/go-critic/go-critic/checkers\n")
			fmt.Printf("Tags: [%s]\n\n", strings.Join(c.tags, " "))
			fmt.Printf("%s\n\n", c.description)
			fmt.Printf("Non-compliant code:\n%s\n\n", c.nonCompliant)
			fmt.Printf("Compliant code:\n%s\n", c.compliant)
			return
		}
	}
	fmt.Printf("checker %s not found\n", name)
}

func hasTag(c checker, tag string) bool {
	for _, t := range c.tags {
		if "#"+t == tag {
			return true
		}
	}
	return false
}

func handleCheck(args []string) {
	fs := flag.NewFlagSet("check", flag.ContinueOnError)
	enable := fs.String("enable", "", "")
	disable := fs.String("disable", "", "")
	enableAll := fs.Bool("enableAll", false, "")
	verbose := fs.Bool("v", false, "")
	fs.Usage = func() {}

	err := fs.Parse(args)
	if err != nil {
		return
	}

	targets := fs.Args()
	if len(targets) == 0 {
		targets = []string{"."}
	}

	enabledMap := make(map[string]bool)
	for _, c := range checkers {
		isEnabled := true
		for _, t := range c.tags {
			if t == "experimental" || t == "opinionated" {
				isEnabled = false
				break
			}
		}
		if *enableAll {
			isEnabled = true
		}
		enabledMap[c.name] = isEnabled
	}

	if *enable != "" {
		for _, name := range strings.Split(*enable, ",") {
			if strings.HasPrefix(name, "#") {
				for _, c := range checkers {
					if hasTag(c, name) {
						enabledMap[c.name] = true
					}
				}
			} else {
				enabledMap[name] = true
			}
		}
	}

	if *disable != "" {
		for _, name := range strings.Split(*disable, ",") {
			if strings.HasPrefix(name, "#") {
				for _, c := range checkers {
					if hasTag(c, name) {
						enabledMap[c.name] = false
					}
				}
			} else {
				enabledMap[name] = false
			}
		}
	}

	if *verbose {
		var names []string
		for _, c := range checkers {
			names = append(names, c.name)
		}
		sort.Strings(names)
		for _, name := range names {
			if !enabledMap[name] {
				fmt.Printf("\tdebug: %s: not enabled by name or tag (-enable)\n", name)
			}
		}
		for _, name := range names {
			if enabledMap[name] {
				fmt.Printf("\tdebug: %s is enabled\n", name)
			}
		}
	}

	var allIssues []issue
	for _, target := range targets {
		if strings.HasSuffix(target, "/...") {
			dir := strings.TrimSuffix(target, "/...")
			filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
				if err == nil && !info.IsDir() && strings.HasSuffix(path, ".go") {
					allIssues = append(allIssues, runCheckersOnFile(path, enabledMap)...)
				}
				return nil
			})
		} else {
			info, err := os.Stat(target)
			if err != nil {
				allIssues = append(allIssues, runCheckersOnFile(target, enabledMap)...)
				continue
			}
			if info.IsDir() {
				files, _ := filepath.Glob(filepath.Join(target, "*.go"))
				for _, f := range files {
					allIssues = append(allIssues, runCheckersOnFile(f, enabledMap)...)
				}
			} else {
				allIssues = append(allIssues, runCheckersOnFile(target, enabledMap)...)
			}
		}
	}

	if len(allIssues) > 0 {
		sort.Slice(allIssues, func(i, j int) bool {
			if allIssues[i].pos.Filename != allIssues[j].pos.Filename {
				return allIssues[i].pos.Filename < allIssues[j].pos.Filename
			}
			if allIssues[i].pos.Line != allIssues[j].pos.Line {
				return allIssues[i].pos.Line < allIssues[j].pos.Line
			}
			return allIssues[i].pos.Column < allIssues[j].pos.Column
		})
		for _, iss := range allIssues {
			fmt.Printf("%s:%d:%d: %s: %s\n", iss.pos.Filename, iss.pos.Line, iss.pos.Column, iss.checker, iss.message)
		}
		os.Exit(1)
	}
}

func nodeToString(fset *token.FileSet, n ast.Node) string {
	var buf bytes.Buffer
	printer.Fprint(&buf, fset, n)
	return buf.String()
}

func runCheckersOnFile(path string, enabledMap map[string]bool) []issue {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		return nil
	}

	var issues []issue

	// Helper for ifElseChain to avoid double reporting
	skipIf := make(map[ast.Node]bool)

	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			return true
		}

		// assignOp
		if enabledMap["assignOp"] {
			if assign, ok := n.(*ast.AssignStmt); ok && len(assign.Lhs) == 1 && len(assign.Rhs) == 1 && assign.Tok == token.ASSIGN {
				if binary, ok := assign.Rhs[0].(*ast.BinaryExpr); ok {
					lhs := nodeToString(fset, assign.Lhs[0])
					blhs := nodeToString(fset, binary.X)
					brhs := nodeToString(fset, binary.Y)

					var replacement string
					if lhs == blhs {
						switch binary.Op {
						case token.ADD:
							if brhs == "1" { replacement = lhs + "++" } else { replacement = fmt.Sprintf("%s += %s", lhs, brhs) }
						case token.SUB:
							if brhs == "1" { replacement = lhs + "--" } else { replacement = fmt.Sprintf("%s -= %s", lhs, brhs) }
						case token.MUL: replacement = fmt.Sprintf("%s *= %s", lhs, brhs)
						case token.QUO: replacement = fmt.Sprintf("%s /= %s", lhs, brhs)
						case token.REM: replacement = fmt.Sprintf("%s %%= %s", lhs, brhs)
						case token.AND: replacement = fmt.Sprintf("%s &= %s", lhs, brhs)
						case token.OR:  replacement = fmt.Sprintf("%s |= %s", lhs, brhs)
						case token.XOR: replacement = fmt.Sprintf("%s ^= %s", lhs, brhs)
						case token.SHL: replacement = fmt.Sprintf("%s <<= %s", lhs, brhs)
						case token.SHR: replacement = fmt.Sprintf("%s >>= %s", lhs, brhs)
						}
					}
					if replacement != "" {
						issues = append(issues, issue{
							pos: fset.Position(assign.Pos()),
							checker: "assignOp",
							message: fmt.Sprintf("replace `%s = %s %s %s` with `%s`", lhs, blhs, binary.Op, brhs, replacement),
						})
					}
				}
			}
		}

		// elseif
		if enabledMap["elseif"] {
			if ifStmt, ok := n.(*ast.IfStmt); ok && ifStmt.Else != nil {
				if block, ok := ifStmt.Else.(*ast.BlockStmt); ok && len(block.List) == 1 {
					if _, ok := block.List[0].(*ast.IfStmt); ok {
						issues = append(issues, issue{
							pos: fset.Position(ifStmt.Else.Pos()),
							checker: "elseif",
							message: "can replace 'else {if cond {}}' with 'else if cond {}'",
						})
					}
				}
			}
		}

		// unslice
		if enabledMap["unslice"] {
			if slice, ok := n.(*ast.SliceExpr); ok && slice.Low == nil && slice.High == nil && slice.Max == nil {
				s := nodeToString(fset, slice.X)
				issues = append(issues, issue{
					pos: fset.Position(slice.Pos()),
					checker: "unslice",
					message: fmt.Sprintf("could simplify %s[:] to %s", s, s),
				})
			}
		}

		// ifElseChain
		if enabledMap["ifElseChain"] && !skipIf[n] {
			if ifStmt, ok := n.(*ast.IfStmt); ok {
				count := 0
				curr := ifStmt
				for curr.Else != nil {
					if nextIf, ok := curr.Else.(*ast.IfStmt); ok {
						count++
						skipIf[nextIf] = true
						curr = nextIf
					} else {
						// else block
						count++
						break
					}
				}
				if count >= 2 {
					issues = append(issues, issue{
						pos: fset.Position(ifStmt.Pos()),
						checker: "ifElseChain",
						message: "rewrite if-else to switch statement",
					})
				}
			}
		}

		return true
	})
	return issues
}
